import { expr, sanitizeName, scopedResourceLabel, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { ROLE_RESOURCE_TYPE } from "../org/role.js";
import { SERVICE_ACCOUNT_RESOURCE_TYPE } from "../service-account/module.js";
function principals(values, type, where, orgRefs, diagnostics) {
    if (values === undefined || values.length === 0)
        return undefined;
    const out = [];
    for (const value of values) {
        const user = value;
        if (type === "elementum_user" && user?.__kind === "user" && user.email) {
            const label = sanitizeName(user.email.split("@", 1)[0] ?? user.email);
            orgRefs.rawLookup(type, label, user.email);
            out.push(expr.dataAttr(type, label, ["id"]));
            continue;
        }
        const token = value;
        if (type === "elementum_group" && token?.__kind === "group") {
            const resolved = orgRefs.byTsLabel("groups", token.refName ?? "");
            if (resolved === undefined)
                diagnostics.push(`${where}: group token ${JSON.stringify(token.refName ?? "")} is not in org.ts; dropped`);
            else
                out.push(expr.dataAttr(type, resolved.tfLabel, ["id"]));
            continue;
        }
        diagnostics.push(`${where}: unrecognized typed principal; dropped`);
    }
    return out.length > 0 ? out : undefined;
}
export function rolesToTf(roles, opts) {
    return Object.entries(roles ?? {}).map(([key, role]) => {
        const attrs = { object_id: opts.objectId, name: role.name };
        if (role.description !== undefined)
            attrs["description"] = role.description;
        if (role.autoShare !== undefined)
            attrs["auto_share"] = [...role.autoShare].sort();
        const users = principals(role.users, "elementum_user", `roles.${key}.users`, opts.orgRefs, opts.diagnostics);
        const groups = principals(role.groups, "elementum_group", `roles.${key}.groups`, opts.orgRefs, opts.diagnostics);
        if (users !== undefined)
            attrs["user_ids"] = users;
        if (groups !== undefined)
            attrs["group_ids"] = groups;
        if (role.serviceAccounts !== undefined) {
            attrs["service_account_ids"] = role.serviceAccounts.flatMap((account) => {
                if (account.appRefName !== opts.ownerRefName) {
                    opts.diagnostics.push(`roles.${key}.serviceAccounts: ${JSON.stringify(account.name)} belongs to app ${JSON.stringify(account.appRefName)}, not ${JSON.stringify(opts.ownerRefName)}; dropped`);
                    return [];
                }
                const local = Object.entries(opts.serviceAccounts ?? {}).find(([, candidate]) => `${candidate.firstName} ${candidate.lastName}` === account.name);
                if (local !== undefined)
                    return [expr.resourceAttr(SERVICE_ACCOUNT_RESOURCE_TYPE, scopedResourceLabel(opts.ownerTfLabel, tsLabelToTfLabel(local[0]), "app"), ["id"])];
                const label = sanitizeName(account.name);
                opts.orgRefs.rawLookup(SERVICE_ACCOUNT_RESOURCE_TYPE, label, account.name, { app_id: opts.objectId });
                return [expr.dataAttr(SERVICE_ACCOUNT_RESOURCE_TYPE, label, ["id"])];
            });
        }
        if (role.permissions !== undefined)
            attrs["permissions"] = [...role.permissions].sort((a, b) => a.group.localeCompare(b.group)).map((permission) => ({
                group: permission.group,
                level: permission.level,
                ...(permission.customPermissions !== undefined && { custom_permissions: [...permission.customPermissions] }),
            }));
        return {
            kind: "resource",
            type: ROLE_RESOURCE_TYPE,
            label: scopedResourceLabel(opts.ownerTfLabel, tsLabelToTfLabel(key), opts.scope),
            attrs,
        };
    });
}
